  function isMissing(value){ return value===null||value===undefined||value===''; }
  function definition(field){ const value=FIELDS[field]; if(!value) throw new Error(`Unknown V2 public Hex field: ${field}`); return value; }
  function read(record,field){ definition(field); if(!record||!Object.prototype.hasOwnProperty.call(record,field)) return {state:'missing',value:null}; const value=record[field]; return isMissing(value)?{state:'missing',value:null}:{state:'observed',value}; }
  function number(record,field){ const reading=read(record,field); if(reading.state==='missing') return reading; const value=Number(reading.value); return Number.isFinite(value)?{state:'observed',value}:{state:'invalid',value:null}; }
  function text(record,field){ const reading=read(record,field); return reading.state==='missing'?reading:{state:'observed',value:String(reading.value)}; }
  function format(record,field,options={}){ const def=definition(field); const reading=read(record,field); if(reading.state==='missing') return options.nullLabel||'Not assessed'; if(def.data_type==='REAL'||def.data_type==='INTEGER'){ const n=Number(reading.value); if(!Number.isFinite(n)) return options.nullLabel||'Not assessed'; const digits=Number.isInteger(options.decimals)?options.decimals:(def.data_type==='INTEGER'?0:3); return n.toLocaleString('en-GB',{maximumFractionDigits:digits}); } return String(reading.value); }
  function adaptHexReport(record){ if(!record) return null; const id=text(record,'hex_id'); if(id.state!=='observed') throw new Error('Hex report lacks hex_id.'); return Object.freeze({grain:'hex',hexId:id.value,record,methodVersion:record.public_release_method_version||null}); }
